Buffer& operator=(const Buffer& o) {
    if (this == &o) return *this;
    int* fresh = new int[o.n];
    std::copy(o.data, o.data + o.n, fresh);
    delete[] data;      // free OLD memory
    data = fresh;
    n = o.n;
    return *this;
}
